import subprocess,json
from pathlib import Path
from concurrent.futures import ThreadPoolExecutor
base=Path('/scratch/e1583364/cvpr2027')
print('DIRECTORIES: '+json.dumps([p.name for p in base.iterdir() if p.is_dir()]),flush=True)
targets=[base/'cache',base/'t02_export',base/'t02_export_parallel',base/'t01v2',base/'t00b',base/'smoke_e2e',base/'shared_gpu_queue']
def run(p):
 if not p.exists(): return {'path':str(p),'exists':False}
 try:
  r=subprocess.run(['du','-h','--max-depth=1',str(p)],text=True,capture_output=True,timeout=35)
  return {'path':str(p),'exit_code':r.returncode,'stdout':r.stdout,'stderr':r.stderr}
 except subprocess.TimeoutExpired as e:
  return {'path':str(p),'timed_out':True,'stdout':e.stdout.decode() if isinstance(e.stdout,bytes) else e.stdout}
for value in ThreadPoolExecutor(max_workers=2).map(run,targets):print(json.dumps(value),flush=True)

